import{_ as i,o as e,c as a,an as t}from"./chunks/framework.gM3-hPsp.js";const k=JSON.parse('{"title":"GPU & Precision","description":"","frontmatter":{},"headers":[],"relativePath":"gpu.md","filePath":"gpu.md","lastUpdated":null}'),n={name:"gpu.md"};function o(l,s,h,r,p,c){return e(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="GPU-and-Precision" tabindex="-1">GPU &amp; Precision <a class="header-anchor" href="#GPU-and-Precision" aria-label="Permalink to &quot;GPU &amp; Precision {#GPU-and-Precision}&quot;">​</a></h1><p>MicroMagnetic.jl runs on the CPU by default and supports NVIDIA, AMD, Intel and Apple GPUs through <a href="https://github.com/JuliaGPU/KernelAbstractions.jl" target="_blank" rel="noreferrer">KernelAbstractions.jl</a>. This page explains the three session-level settings — <strong>backend</strong>, <strong>precision</strong> and <strong>group size</strong> — and the one rule you need to remember:</p><div class="warning custom-block"><p class="custom-block-title">Settings are constructor-time defaults</p><p><code>set_backend</code>, <code>set_precision</code> and <code>set_groupsize</code> only affect simulations created <strong>after</strong> the call. A <code>Sim</code> freezes its precision into its type and its backend into its data at construction time; later changes to the global settings never touch an existing simulation.</p></div><h2 id="Backends" tabindex="-1">Backends <a class="header-anchor" href="#Backends" aria-label="Permalink to &quot;Backends {#Backends}&quot;">​</a></h2><p>Install one of the GPU packages listed on the <a href="./install">installation page</a> and load it through the <code>@using_gpu</code> macro, which imports whichever backend package is available in your environment:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MicroMagnetic</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@using_gpu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># loads CUDA, AMDGPU, oneAPI or Metal if installed, else stays on CPU</span></span></code></pre></div><p>The macro switches the default backend automatically. If you need manual control:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cuda&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># allocations after this call go to the GPU</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cpu&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># back to CPU</span></span></code></pre></div><p>Running <code>set_backend</code> when simulations already exist prints a warning — the running simulations keep their data where they are.</p><h2 id="Precision" tabindex="-1">Precision <a class="header-anchor" href="#Precision" aria-label="Permalink to &quot;Precision {#Precision}&quot;">​</a></h2><p>The default working precision is <code>Float64</code>. Single precision usually doubles the throughput on consumer GPUs (FP64 throughput is 1/32 of FP32 on GeForce cards) and halves the memory footprint:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_precision</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Float32)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># simulations created after this line use Float32</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sim </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Sim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(mesh; driver</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;LLG&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Allowed values are <code>Float64</code>, <code>Float32</code> and <code>AbstractFloat</code>:</p><ul><li><p><code>Float64</code> / <code>Float32</code> — concrete precision for production runs.</p></li><li><p><code>AbstractFloat</code> — a <strong>symbolic mode</strong> used only by the eigenmode workflow; it lets parameters carry symbolic terms. Regular simulations fail in this mode, in particular on GPUs (device arrays cannot hold an abstract element type).</p></li></ul><div class="tip custom-block"><p class="custom-block-title">Set precision before creating simulations</p><p>Because precision is frozen into the simulation type at construction, call <code>set_precision</code> <strong>before</strong> <code>Sim(...)</code> / <code>CubicMesh(...)</code> / <code>FDMesh(...)</code>. Mixing precisions across simulations in one session is not supported.</p></div><h3 id="The-eigenmode-exception" tabindex="-1">The eigenmode exception <a class="header-anchor" href="#The-eigenmode-exception" aria-label="Permalink to &quot;The eigenmode exception {#The-eigenmode-exception}&quot;">​</a></h3><p>The eigenmode analysis requires the symbolic mode, which changes the global precision for the <strong>whole session</strong> and is not restored automatically. After finishing an eigenmode calculation, restore the concrete precision before creating further simulations:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ... eigenmode analysis with set_precision(AbstractFloat) ...</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_precision</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Float64)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># restore before the next simulation</span></span></code></pre></div><p>See the <a href="./eigen/eigenmodes">eigenmode analysis</a> page for the full workflow.</p><h2 id="Group-size" tabindex="-1">Group size <a class="header-anchor" href="#Group-size" aria-label="Permalink to &quot;Group size {#Group-size}&quot;">​</a></h2><p><code>set_groupsize</code> controls the thread-group size used when launching GPU kernels (default 256). It is a pure performance knob — it never affects results:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_groupsize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">128</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># tune only if profiling suggests it</span></span></code></pre></div><h2 id="Checking-what-is-active" tabindex="-1">Checking what is active <a class="header-anchor" href="#Checking-what-is-active" aria-label="Permalink to &quot;Checking what is active {#Checking-what-is-active}&quot;">​</a></h2><p>After <code>using MicroMagnetic</code> the startup message reports the active backend. In a script you can verify the frozen precision through the simulation itself:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sim </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Sim</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(mesh; driver</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;LLG&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">eltype</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sim</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">spin)                    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># the working precision of this simulation</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Benchmark before tuning</p><p>For anything performance related — group size, precision, backend — measure with <code>MicroMagnetic.timer</code> before and after; the Timings section on the <a href="./basics">basics page</a> shows how the report looks.</p></div>`,26)])])}const g=i(n,[["render",o]]);export{k as __pageData,g as default};
